import { useParams, Link } from 'react-router-dom';
import { useEffect, useState, Suspense } from 'react';
import { products } from '@/data/products';
import { ProductCard } from '@/components/ProductCard';
import { RatingStars } from '@/components/RatingStars';
import { useCart } from '@/context/CartContext';
import { useAuth } from '@/context/AuthContext';
import { apiFetch } from '@/lib/api';
import { Product3DRenderer } from '@/lib/product3d';

interface BackendProductPayload {
  id: number;
  rating_avg: number;
  rating_count: number;
}

interface BackendReview {
  review_id: string;
  user_name: string;
  rating: number;
  review_text: string | null;
  review_date: string;
}

// 3D Viewer Component using the new Product3DRenderer
function ProductViewer3D({ slug }: { slug: string }) {
  return (
    <div className="w-full h-full min-h-[400px]">
      <Suspense fallback={
        <div className="w-full h-full flex items-center justify-center bg-archive-100">
          <div className="w-8 h-8 border-2 border-archive-300 border-t-archive-700 rounded-full animate-spin" />
        </div>
      }>
        <Product3DRenderer
          slug={slug}
          className="w-full h-full"
          interactive={true}
          autoRotate={true}
          showLoader={true}
        />
      </Suspense>
    </div>
  );
}

export function ProductDetail() {
  const { id } = useParams<{ id: string }>();
  const { addToCart } = useCart();
  const { isLoggedIn, isAuthLoading, isSaved, toggleSavedItem, setIsAuthModalOpen, setAuthModalMode, getAuthHeaders } = useAuth();
  const [show3D, setShow3D] = useState(false);
  const [addedToCart, setAddedToCart] = useState(false);
  const [userRating, setUserRating] = useState<number | null>(null);
  const [backendProductId, setBackendProductId] = useState<number | null>(null);
  const [backendAverageRating, setBackendAverageRating] = useState<number | null>(null);
  const [backendRatingCount, setBackendRatingCount] = useState<number | null>(null);
  const [reviews, setReviews] = useState<BackendReview[]>([]);
  const [reviewText, setReviewText] = useState('');
  const [isSubmittingReview, setIsSubmittingReview] = useState(false);
  const [reviewError, setReviewError] = useState<string | null>(null);

  const product = products.find(p => p.id === id);
  const relatedProducts = products
    .filter(p => p.id !== id && (p.category === product?.category || p.era === product?.era))
    .slice(0, 4);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [id]);

  useEffect(() => {
    setReviewError(null);
    setBackendProductId(null);
    setBackendAverageRating(null);
    setBackendRatingCount(null);
    setReviews([]);
    setUserRating(null);

    if (!id) {
      return;
    }

    const fetchBackendProduct = async () => {
      try {
        const res = await apiFetch(`/product/${id}/?format=json`);
        if (res.ok) {
          const data = (await res.json()) as BackendProductPayload;
          setBackendProductId(data.id);
          setBackendAverageRating(Number(data.rating_avg) || 0);
          setBackendRatingCount(Number(data.rating_count) || 0);
          return;
        }

        // Try slug-filtered API query before full list scan
        const slugRes = await apiFetch(`/api/products/?slug=${encodeURIComponent(id)}`);
        if (slugRes.ok) {
          const slugItems = (await slugRes.json()) as Array<BackendProductPayload & { slug?: string; name?: string }>;
          if (slugItems.length > 0) {
            const matched = slugItems[0];
            setBackendProductId(matched.id);
            setBackendAverageRating(Number(matched.rating_avg) || 0);
            setBackendRatingCount(Number(matched.rating_count) || 0);
            return;
          }
        }

        const listRes = await apiFetch('/api/products/');
        if (!listRes.ok) {
          return;
        }

        const items = (await listRes.json()) as Array<BackendProductPayload & { slug?: string; name?: string }>;
        const matched = items.find((item) => item.slug === id)
          ?? items.find((item) => product?.name && item.name === product.name);

        if (matched) {
          setBackendProductId(matched.id);
          setBackendAverageRating(Number(matched.rating_avg) || 0);
          setBackendRatingCount(Number(matched.rating_count) || 0);
        }
      } catch {
        // Keep UI usable with catalog fallback data if backend detail fails.
      }
    };

    fetchBackendProduct();
  }, [id, product?.name]);

  useEffect(() => {
    if (!backendProductId) {
      return;
    }

    const fetchReviews = async () => {
      try {
        const res = await apiFetch(`/api/products/${backendProductId}/reviews/`);
        if (!res.ok) {
          return;
        }
        const data = (await res.json()) as BackendReview[];
        setReviews(data);
      } catch {
        // Keep page functional if reviews request fails.
      }
    };

    fetchReviews();
  }, [backendProductId]);

  if (!product) {
    return (
      <div className="pt-32 pb-20 text-center">
        <div className="max-w-[1800px] mx-auto px-6 md:px-12">
          <h1 className="font-editorial text-3xl text-archive-900 mb-4">Artifact Not Found</h1>
          <p className="text-archive-500 mb-6">This piece may have been acquired by another collector.</p>
          <Link
            to="/catalog"
            className="inline-flex items-center gap-2 text-archive-900 border-b border-archive-900 pb-1"
          >
            Browse Collection
          </Link>
        </div>
      </div>
    );
  }

  const handleAddToCart = () => {
    if (!isLoggedIn) {
      setAuthModalMode('login');
      setIsAuthModalOpen(true);
      return;
    }
    addToCart(product);
    setAddedToCart(true);
    setTimeout(() => setAddedToCart(false), 2000);
  };

  const handleSave = () => {
    if (!isLoggedIn) {
      setAuthModalMode('login');
      setIsAuthModalOpen(true);
      return;
    }
    toggleSavedItem(product.id);
  };

  const handleRate = (value: number) => {
    if (isAuthLoading) return;
    if (!isLoggedIn && !localStorage.getItem('archives-token')) {
      setAuthModalMode('login');
      setIsAuthModalOpen(true);
      return;
    }

    setUserRating(value);
    setReviewError(null);
  };

  const submitReview = async () => {
    if (isAuthLoading) return;
    if (!isLoggedIn && !localStorage.getItem('archives-token')) {
      setAuthModalMode('login');
      setIsAuthModalOpen(true);
      return;
    }

    if (!userRating) {
      setReviewError('Please select a star rating first.');
      return;
    }

    let resolvedProductId = backendProductId;

    if (!resolvedProductId) {
      try {
        const linkRes = await apiFetch('/api/link-product/', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...getAuthHeaders(),
          },
          body: JSON.stringify({
            slug: id,
            name: product.name,
            category: product.category,
            description: product.description,
            price: product.price,
          }),
        });

        const linked = await linkRes.json();
        if (!linkRes.ok || !linked?.id) {
          throw new Error(linked?.message || 'This product is not linked to backend data yet.');
        }

        resolvedProductId = Number(linked.id);
        setBackendProductId(resolvedProductId);
      } catch (error) {
        const message = error instanceof Error ? error.message : 'This product is not linked to backend data yet.';
        setReviewError(message);
        return;
      }
    }

    setIsSubmittingReview(true);
    setReviewError(null);
    try {
      const res = await apiFetch(`/api/products/${resolvedProductId}/rate/`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...getAuthHeaders(),
        },
        body: JSON.stringify({
          rating: userRating,
          review_text: reviewText,
        }),
      });

      const data = await res.json();
      if (res.status === 401 || res.status === 403) {
        setAuthModalMode('login');
        setIsAuthModalOpen(true);
        throw new Error('Please sign in to submit your review.');
      }

      if (!res.ok) {
        throw new Error(data?.error || data?.detail || data?.message || 'Failed to submit review');
      }

      setUserRating(userRating);
      setBackendAverageRating(Number(data.rating_avg) || 0);
      setBackendRatingCount(Number(data.rating_count) || 0);
      setReviewText('');

      const reviewsRes = await apiFetch(`/api/products/${resolvedProductId}/reviews/`);
      if (reviewsRes.ok) {
        const latestReviews = (await reviewsRes.json()) as BackendReview[];
        setReviews(latestReviews);
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Failed to submit review';
      setReviewError(message);
    } finally {
      setIsSubmittingReview(false);
    }
  };

  const saved = isSaved(product.id);
  const displayRating = backendAverageRating ?? product.rating;
  const displayRatingCount = backendRatingCount ?? product.ratingCount;
  const ratingLabel = displayRatingCount === 1 ? 'rating' : 'ratings';

  return (
    <div className="pt-24 pb-20">
      {/* Breadcrumb */}
      <div className="max-w-[1800px] mx-auto px-6 md:px-12 py-6">
        <nav className="flex items-center gap-2 text-sm text-archive-500">
          <Link to="/" className="hover:text-archive-900 transition-colors">Home</Link>
          <span>/</span>
          <Link to="/catalog" className="hover:text-archive-900 transition-colors">Collection</Link>
          <span>/</span>
          <span className="text-archive-700 truncate">{product.name}</span>
        </nav>
      </div>

      {/* Main Content */}
      <div className="max-w-[1800px] mx-auto px-6 md:px-12">
        <div className="grid lg:grid-cols-2 gap-12 lg:gap-20">
          {/* Left: Image/3D Viewer */}
          <div className="space-y-4">
            <div className="aspect-square bg-archive-100 rounded-lg overflow-hidden relative">
              {show3D ? (
                <ProductViewer3D slug={product.id} />
              ) : (
                <img
                  src={product.images[0]}
                  alt={product.name}
                  className="w-full h-full object-cover animate-fade-in"
                />
              )}
              
              {/* Toggle 3D */}
              <button
                onClick={() => setShow3D(!show3D)}
                className="absolute bottom-4 right-4 px-4 py-2 rounded-full text-[0.62rem] uppercase tracking-[0.16em] font-mono flex items-center gap-2 transition-colors arc-glass-panel"
                style={{ background: 'var(--arc-glass-dark)' }}
              >
                {show3D ? (
                  <>
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                    </svg>
                    View Image
                  </>
                ) : (
                  <>
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M14 10l-2 1m0 0l-2-1m2 1v2.5M20 7l-2 1m2-1l-2-1m2 1v2.5M14 4l-2-1-2 1M4 7l2-1M4 7l2 1M4 7v2.5M12 21l-2-1m2 1l2-1m-2 1v-2.5M6 18l-2-1v-2.5M18 18l2-1v-2.5" />
                    </svg>
                    View in 3D
                  </>
                )}
              </button>
            </div>
            
            {/* Instructions when 3D is active */}
            {show3D && (
              <p className="text-sm text-archive-500 text-center animate-fade-in">
                Drag to rotate · Auto-rotating display
              </p>
            )}
          </div>

          {/* Right: Details */}
          <div className="lg:pt-8">
            <div className="stagger-children">
              {/* Era & Category */}
              <p className="text-sm uppercase tracking-[0.2em] text-archive-500 mb-4">
                {product.era} · {product.category}
              </p>

              {/* Name */}
              <h1 className="font-display text-4xl md:text-5xl lg:text-6xl text-archive-900 mb-4">
                {product.name}
              </h1>

              {/* Tagline */}
              <p className="font-editorial text-xl text-archive-600 italic mb-8">
                "{product.tagline}"
              </p>

              {/* Price */}
              <div className="flex items-baseline gap-4 mb-8 pb-8 border-b border-archive-200">
                <span className="font-editorial text-4xl text-archive-900">
                  ${product.price.toLocaleString()}
                </span>
                <span className="text-sm text-archive-500">
                  Includes authentication certificate
                </span>
              </div>

              {/* Description */}
              <div className="mb-8">
                <h2 className="text-sm uppercase tracking-wider text-archive-500 mb-4">About This Piece</h2>
                <p className="text-archive-700 leading-relaxed">
                  {product.longDescription}
                </p>
              </div>

              {/* Specs */}
              <div className="mb-8">
                <h2 className="text-sm uppercase tracking-wider text-archive-500 mb-4">Specifications</h2>
                <dl className="grid grid-cols-2 gap-4">
                  {product.specs.map((spec) => (
                    <div key={spec.label} className="py-3 border-b border-archive-100">
                      <dt className="text-sm text-archive-500">{spec.label}</dt>
                      <dd className="text-archive-900">{spec.value}</dd>
                    </div>
                  ))}
                </dl>
              </div>

              {/* Actions */}
              <div className="flex flex-col sm:flex-row gap-4">
                <button
                  onClick={handleAddToCart}
                  className={`flex-1 py-4 text-sm uppercase tracking-wider transition-all duration-300 ${
                    addedToCart
                      ? 'bg-green-700 text-cream'
                      : 'bg-archive-900 text-cream hover:bg-archive-800'
                  }`}
                >
                  {addedToCart ? '✓ Added to Collection' : isLoggedIn ? 'Add to Collection' : 'Sign in to Add'}
                </button>
                <button
                  onClick={handleSave}
                  className={`px-6 py-4 border transition-colors ${
                    saved 
                      ? 'border-archive-900 bg-archive-900 text-cream' 
                      : 'border-archive-300 text-archive-700 hover:border-archive-500'
                  }`}
                  aria-label={saved ? 'Remove from saved' : 'Save item'}
                >
                  <svg 
                    className="w-5 h-5" 
                    fill={saved ? 'currentColor' : 'none'} 
                    stroke="currentColor" 
                    viewBox="0 0 24 24"
                  >
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
                  </svg>
                </button>
              </div>

              <div className="mt-8 pb-8 border-b border-archive-200">
                <div className="flex items-center gap-3">
                  <RatingStars rating={displayRating} size={18} />
                  <span className="text-archive-700">
                    {displayRating.toFixed(1)} ({displayRatingCount} {ratingLabel})
                  </span>
                </div>
                <div className="mt-4">
                  <p className="text-sm uppercase tracking-wider text-archive-500 mb-3">Rate this artifact</p>
                  <div className="flex items-center gap-2">
                    {Array.from({ length: 5 }, (_, index) => {
                      const value = index + 1;
                      const isActive = userRating ? value <= userRating : false;
                      return (
                        <button
                          key={value}
                          type="button"
                          onClick={() => handleRate(value)}
                          className={`w-9 h-9 flex items-center justify-center rounded-full border transition-colors ${
                            isActive
                              ? 'border-archive-900 bg-archive-900 text-cream'
                              : 'border-archive-300 text-archive-700 hover:border-archive-500'
                          }`}
                          aria-label={`Rate ${value} out of 5`}
                          aria-pressed={userRating === value}
                        >
                          <svg
                            className="w-4 h-4"
                            fill="currentColor"
                            viewBox="0 0 24 24"
                          >
                            <path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.62L12 2 9.19 8.62 2 9.24l5.46 4.73L5.82 21z" />
                          </svg>
                        </button>
                      );
                    })}
                    <span className="text-sm text-archive-500">
                      {userRating ? `Selected rating: ${userRating}/5` : 'Tap a star to rate'}
                    </span>
                  </div>

                  <div className="mt-4 space-y-3">
                    <textarea
                      value={reviewText}
                      onChange={(event) => setReviewText(event.target.value)}
                      placeholder="Share your thoughts about this product"
                      rows={3}
                      className="w-full rounded-md border border-archive-200 bg-white px-3 py-2 text-sm text-archive-800 outline-none transition-colors focus:border-archive-500"
                    />
                    <button
                      type="button"
                      onClick={submitReview}
                      disabled={!userRating || isSubmittingReview || isAuthLoading}
                      className="px-4 py-2 text-xs uppercase tracking-wider bg-archive-900 text-cream disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      {isAuthLoading ? 'Loading...' : isSubmittingReview ? 'Submitting...' : 'Submit Review'}
                    </button>
                    {reviewError && (
                      <p className="text-sm text-red-600">{reviewError}</p>
                    )}
                  </div>
                </div>
              </div>

              <div className="mt-8">
                <h3 className="text-sm uppercase tracking-wider text-archive-500 mb-4">Collector Reviews</h3>
                {reviews.length === 0 ? (
                  <p className="text-sm text-archive-500">No reviews yet. Be the first to review this product.</p>
                ) : (
                  <div className="space-y-4 max-h-72 overflow-auto pr-2">
                    {reviews.map((review) => (
                      <div key={review.review_id} className="border border-archive-200 rounded-md p-4">
                        <div className="flex items-center justify-between gap-4 mb-2">
                          <p className="text-sm font-medium text-archive-900">{review.user_name || 'Collector'}</p>
                          <div className="flex items-center gap-2">
                            <RatingStars rating={review.rating} size={14} />
                            <span className="text-xs text-archive-500">{review.rating.toFixed(1)}</span>
                          </div>
                        </div>
                        {review.review_text && (
                          <p className="text-sm text-archive-700 leading-relaxed">{review.review_text}</p>
                        )}
                        <p className="text-xs text-archive-400 mt-2">{new Date(review.review_date).toLocaleDateString()}</p>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              {/* Trust Badges */}
              <div className="mt-8 pt-8 border-t border-archive-200 grid grid-cols-3 gap-4 text-center">
                <div>
                  <svg className="w-6 h-6 mx-auto text-archive-400 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" />
                  </svg>
                  <p className="text-xs text-archive-500">Authenticated</p>
                </div>
                <div>
                  <svg className="w-6 h-6 mx-auto text-archive-400 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" />
                  </svg>
                  <p className="text-xs text-archive-500">Secure Shipping</p>
                </div>
                <div>
                  <svg className="w-6 h-6 mx-auto text-archive-400 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                  </svg>
                  <p className="text-xs text-archive-500">14-Day Returns</p>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Related Products */}
        {relatedProducts.length > 0 && (
          <section className="mt-32">
            <div className="flex items-end justify-between gap-6 mb-12">
              <div>
                <p className="text-sm uppercase tracking-[0.3em] text-archive-500 mb-4">
                  Related Artifacts
                </p>
                <h2 className="font-display text-3xl md:text-4xl text-archive-900">
                  You May Also Appreciate
                </h2>
              </div>
              <Link
                to="/catalog"
                className="hidden md:inline-flex items-center gap-2 text-archive-600 hover:text-archive-900 transition-colors group"
              >
                <span className="text-sm uppercase tracking-wider">View All</span>
                <svg className="w-4 h-4 transition-transform duration-300 group-hover:translate-x-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M17 8l4 4m0 0l-4 4m4-4H3" />
                </svg>
              </Link>
            </div>

            <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-8">
              {relatedProducts.map((relatedProduct) => (
                <ProductCard key={relatedProduct.id} product={relatedProduct} variant="compact" />
              ))}
            </div>
          </section>
        )}
      </div>
    </div>
  );
}
